create table if not exists public.astracore_knowledge_sources (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, source_type text not null, status text not null default 'active', config jsonb not null default '{}', permissions jsonb not null default '{}', tags text[] not null default '{}', last_synced_at timestamptz, error_message text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists astracore_knowledge_sources_user_idx on public.astracore_knowledge_sources(user_id);
create table if not exists public.astracore_knowledge_documents (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, source_id uuid references public.astracore_knowledge_sources(id) on delete set null, title text not null, source text not null, url text, owner text, language text, document_type text not null, permissions jsonb not null default '{}', tags text[] not null default '{}', content_hash text not null, status text not null default 'indexed', page_count integer, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, content_hash));
create index if not exists astracore_knowledge_documents_user_idx on public.astracore_knowledge_documents(user_id);
create table if not exists public.astracore_knowledge_chunks (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.astracore_knowledge_documents(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, chunk_index integer not null, content text not null, language text, page_number integer, embedding extensions.vector(384), metadata jsonb not null default '{}', created_at timestamptz not null default now(), unique(document_id, chunk_index));
create index if not exists astracore_knowledge_chunks_user_idx on public.astracore_knowledge_chunks(user_id);
create index if not exists astracore_knowledge_chunks_document_idx on public.astracore_knowledge_chunks(document_id);
create index if not exists astracore_knowledge_chunks_fts_idx on public.astracore_knowledge_chunks using gin (to_tsvector('simple', content));
create index if not exists astracore_knowledge_chunks_embedding_hnsw_idx on public.astracore_knowledge_chunks using hnsw (embedding vector_cosine_ops) where embedding is not null;
create table if not exists public.astracore_memory_records (memory_id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, content text not null, source text not null default 'user', confidence double precision not null default 1, permission text not null default 'private', expires_at timestamptz, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists astracore_memory_user_idx on public.astracore_memory_records(user_id);
create table if not exists public.astracore_tool_registry (name text primary key, description text not null, input_schema jsonb not null default '{}', output_schema jsonb not null default '{}', permissions jsonb not null default '{}', risk_level text not null default 'low', timeout_ms integer not null default 10000, authentication_requirements jsonb not null default '{}', status text not null default 'not_implemented', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.astracore_audit_events (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, request_id text, event_type text not null, model text, source_ids jsonb not null default '[]', tool_names jsonb not null default '[]', latency_ms integer, metadata jsonb not null default '{}', created_at timestamptz not null default now());

alter table public.astracore_knowledge_sources enable row level security;
alter table public.astracore_knowledge_documents enable row level security;
alter table public.astracore_knowledge_chunks enable row level security;
alter table public.astracore_memory_records enable row level security;
alter table public.astracore_tool_registry enable row level security;
alter table public.astracore_audit_events enable row level security;
revoke all on table public.astracore_knowledge_sources, public.astracore_knowledge_documents, public.astracore_knowledge_chunks, public.astracore_memory_records, public.astracore_tool_registry, public.astracore_audit_events from anon;
grant select,insert,update,delete on table public.astracore_knowledge_sources, public.astracore_knowledge_documents, public.astracore_knowledge_chunks, public.astracore_memory_records to authenticated;
grant select on public.astracore_tool_registry to authenticated;
grant select,insert on public.astracore_audit_events to authenticated;
create policy "knowledge source owner" on public.astracore_knowledge_sources for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "knowledge document owner" on public.astracore_knowledge_documents for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "knowledge chunk owner" on public.astracore_knowledge_chunks for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "memory owner" on public.astracore_memory_records for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "tool registry read" on public.astracore_tool_registry for select to authenticated using (true);
create policy "audit owner" on public.astracore_audit_events for select to authenticated using ((select auth.uid())=user_id);
create policy "audit insert owner" on public.astracore_audit_events for insert to authenticated with check ((select auth.uid())=user_id);

insert into public.astracore_tool_registry(name,description,input_schema,output_schema,risk_level,status) values ('file_search','Search user-owned indexed knowledge.','{}','{}','low','enabled'),('web_search','Search current public web information with source attribution.','{}','{}','medium','not_implemented'),('calculator','Deterministic arithmetic.','{}','{}','low','not_implemented'),('database_query','Controlled read-only database analysis.','{}','{}','high','not_implemented'),('code_execution','Isolated Python execution.','{}','{}','high','not_implemented'),('image_analysis','Processed image understanding.','{}','{}','medium','not_implemented') on conflict (name) do update set description=excluded.description,status=excluded.status,updated_at=now();
